{
  "name": "opencode-yolo-toggle",
  "version": "0.1.0",
  "description": "OpenCode plugin that toggles YOLO permission auto-approval from the TUI command palette.",
  "type": "module",
  "main": "./dist/server.js",
  "exports": {
    "./server": {
      "import": "./dist/server.js"
    },
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "README.md"
